1	package netcheck
2	
3	import (
4		"context"
5		"errors"
6		"net"
7		"strings"
8		"testing"
9	)
10	
11	// routeCheck runs the route stage against prior and returns its one check.
12	func routeCheck(t *testing.T, env Env, tg Target, prior Results) Check {
13		t.Helper()
14		checks := runRoute(context.Background(), tg, env, DefaultSettings(), &prior)
15		if len(checks) != 1 {
16			t.Fatalf("route stage produced %d checks, want 1", len(checks))
17		}
18		return checks[0]
19	}
20	
21	// resolvedTo builds the prior Results a resolve stage would have left behind.
22	func resolvedTo(t *testing.T, ips ...net.IP) Results {
23		t.Helper()
24		env := fakeEnv{resolve: func(context.Context, string, string) ([]net.IP, error) { return ips, nil }}
25		var prior Results
26		return ResultsOf(runResolve(context.Background(), target(), env, DefaultSettings(), &prior)...)
27	}
28	
29	// TestTheRouteStageReadsWhatTheResolveStageWrote pins the coupling this stage
30	// rests on. It takes its addresses from the resolve check's facts rather than
31	// resolving again, so a change to how an address is written there would
32	// silently leave this stage with nothing to route to — and the check would go
33	// Unknown on a machine whose routing table is perfectly readable.
34	func TestTheRouteStageReadsWhatTheResolveStageWrote(t *testing.T) {
35		prior := resolvedTo(t, net.ParseIP("93.184.216.34"), net.ParseIP("2606:2800:220:1::1"))
36	
37		got := targetAddresses(target(), &prior)
38		if len(got) != 2 {
39			t.Fatalf("targetAddresses read %d addresses from the resolve check, want 2: %v", len(got), got)
40		}
41		if got[0].String() != "93.184.216.34" || got[1].String() != "2606:2800:220:1::1" {
42			t.Fatalf("addresses = %v, want the two the resolve stage recorded", got)
43		}
44	}
45	
46	// TestALiteralTargetIsItsOwnAddress covers the case where there is no resolve
47	// check to read: the target is already an address.
48	func TestALiteralTargetIsItsOwnAddress(t *testing.T) {
49		var none Results
50		got := targetAddresses(Target{Host: "10.2.3.4", Port: 443}, &none)
51		if len(got) != 1 || got[0].String() != "10.2.3.4" {
52			t.Fatalf("addresses = %v, want [10.2.3.4]", got)
53		}
54	}
55	
56	// TestTheWayOutIsNamedByItsInterface fixes what the summary says. The gateway
57	// is in the facts; the interface is what the user recognises.
58	func TestTheWayOutIsNamedByItsInterface(t *testing.T) {
59		env := fakeEnv{route: func(context.Context, net.IP) (RouteHop, error) {
60			return RouteHop{
61				Interface: "ProtonVPN",
62				Source:    net.ParseIP("10.2.0.2"),
63			}, nil
64		}}
65	
66		c := routeCheck(t, env, target(), resolvedTo(t, net.ParseIP("93.184.216.34")))
67		if c.Verdict != OK {
68			t.Fatalf("verdict = %v (%s), want OK", c.Verdict, c.Summary)
69		}
70		if !strings.Contains(c.Summary, "ProtonVPN") {
71			t.Fatalf("summary = %q, want the interface named", c.Summary)
72		}
73		if factValue(c, "Source address") != "10.2.0.2" {
74			t.Fatalf("source address fact = %q, want 10.2.0.2", factValue(c, "Source address"))
75		}
76	}
77	
78	// TestADirectlyConnectedTargetSaysSoRatherThanNothing covers the empty gateway.
79	// A blank line where a gateway would be reads as a missing measurement; "no
80	// gateway" is an answer, and it rules out every hop beyond the local segment.
81	func TestADirectlyConnectedTargetSaysSoRatherThanNothing(t *testing.T) {
82		env := fakeEnv{route: func(context.Context, net.IP) (RouteHop, error) {
83			return RouteHop{Interface: "Ethernet 2", Source: net.ParseIP("192.168.1.21")}, nil
84		}}
85	
86		c := routeCheck(t, env, Target{Host: "192.168.1.1", Port: 443}, Results{})
87		if got := factValue(c, "Gateway"); got != "directly connected" {
88			t.Fatalf("gateway fact = %q, want it to state the absence", got)
89		}
90	}
91	
92	// TestARouteLookupThatFailsIsUnknownAndNeverFail is D20 in this stage. A
93	// lookup that could not answer is not a machine with no route, and reporting
94	// the first as the second is precisely the defect this codebase keeps finding.
95	func TestARouteLookupThatFailsIsUnknownAndNeverFail(t *testing.T) {
96		env := fakeEnv{route: func(context.Context, net.IP) (RouteHop, error) {
97			return RouteHop{}, errors.New("network is unreachable")
98		}}
99	
100		c := routeCheck(t, env, target(), resolvedTo(t, net.ParseIP("93.184.216.34")))
101		if c.Verdict != Unknown {
102			t.Fatalf("verdict = %v (%s), want Unknown", c.Verdict, c.Summary)
103		}
104		if strings.Contains(strings.ToLower(c.Summary), "no route") {
105			t.Fatalf("summary = %q — it must not claim there is no route", c.Summary)
106		}
107	}
108	
109	// TestOneFamilyWithoutARouteWarnsRatherThanHidingIt is the IPv6 case, which is
110	// the one worth reporting: a client that prefers IPv6 hangs before falling
111	// back, and every other check in the run reports the symptom instead.
112	func TestOneFamilyWithoutARouteWarnsRatherThanHidingIt(t *testing.T) {
113		env := fakeEnv{route: func(_ context.Context, ip net.IP) (RouteHop, error) {
114			if ip.To4() == nil {
115				return RouteHop{}, errors.New("network is unreachable")
116			}
117			return RouteHop{Interface: "Ethernet 2", Source: net.ParseIP("192.168.1.21")}, nil
118		}}
119	
120		prior := resolvedTo(t, net.ParseIP("93.184.216.34"), net.ParseIP("2606:2800:220:1::1"))
121		c := routeCheck(t, env, target(), prior)
122	
123		if c.Verdict != Warn || c.Reason != ReasonPartialRoute {
124			t.Fatalf("verdict = %v/%q, want Warn/partial-route (%s)", c.Verdict, c.Reason, c.Summary)
125		}
126		if !strings.Contains(c.Summary, "1 of 2") {
127			t.Fatalf("summary = %q, want it to count what is missing", c.Summary)
128		}
129		if factValue(c, "No route") == "" {
130			t.Fatalf("the address without a route is not named in the facts")
131		}
132	}
133	
134	// TestTheRouteStageGatesNothing keeps a machine whose routing table cannot be
135	// read from losing every check below it. The reach stage makes the same
136	// promise for the same reason.
137	func TestTheRouteStageGatesNothing(t *testing.T) {
138		for _, s := range stages() {
139			if s.id == StageRoute && s.gate != "" {
140				t.Fatalf("the route stage gates %q — a routing table that cannot be read "+
141					"must not cascade over the port and the certificate", s.gate)
142			}
143		}
144	}
145	
146	// TestOnlyTheFirstAddressesAreRouted bounds the work for a name behind a large
147	// pool. The question is which way out, not how many addresses there are.
148	func TestOnlyTheFirstAddressesAreRouted(t *testing.T) {
149		var many []net.IP
150		for i := 0; i < maxRoutedAddresses+5; i++ {
151			many = append(many, net.IPv4(93, 184, 216, byte(i)))
152		}
153	
154		got := targetAddresses(target(), func() *Results { r := resolvedTo(t, many...); return &r }())
155		if len(got) != maxRoutedAddresses {
156			t.Fatalf("routed %d addresses, want the cap of %d", len(got), maxRoutedAddresses)
157		}
158	}
159	
160	// factValue returns the first value recorded under key, or "".
161	func factValue(c Check, key string) string {
162		for _, f := range c.Facts {
163			if f.Key == key {
164				return f.Value
165			}
166		}
167		return ""
168	}
169

